mapper.select:
SELECT d.doctor, COALESCE(reg.visitCount, 0) AS visitCount, COALESCE(bill.patientCount, 0) AS patientCount, COALESCE(bill.prescriptionCount, 0) AS prescriptionCount, ROUND(COALESCE(bill.prescriptionFee, 0), 2) AS prescriptionFee, ROUND(COALESCE(sales.actualTotal, 0), 2) AS actualAmount, ROUND(COALESCE(sales.costTotal, 0), 2) AS totalCost, ROUND(COALESCE(sales.actualTotal, 0) - COALESCE(sales.costTotal, 0), 2) AS totalProfit, ROUND(COALESCE(bill.westernDrugFee, 0), 2) AS westernDrugFee, ROUND(COALESCE(bill.chineseHerbalFee, 0), 2) AS chineseHerbalFee, ROUND(COALESCE(bill.chinesePatentFee, 0), 2) AS chinesePatentFee, ROUND(COALESCE(bill.treatmentFee, 0), 2) AS treatmentFee, ROUND(COALESCE(bill.consultFee, 0), 2) AS consultFee, ROUND(COALESCE(bill.materialFee, 0), 2) AS materialFee, ROUND(COALESCE(bill.otherFee, 0), 2) AS otherFee, ROUND(COALESCE(bill.additionalFee, 0), 2) AS additionalFee FROM ( SELECT DISTINCT doctor FROM bq_registration WHERE deleted = 0
AND doctor = #{doctor}
) d LEFT JOIN ( /* 门诊人次 */ SELECT doctor, COUNT(*) AS visitCount FROM bq_registration WHERE deleted = 0 AND orderTime >= #{startTime} AND orderTime <= #{endTime} AND doctor = #{doctor} GROUP BY doctor ) reg ON reg.doctor = d.doctor LEFT JOIN ( /* 收费账单聚合 */ SELECT doctor, COUNT(DISTINCT patientName) AS patientCount, COUNT(*) AS prescriptionCount, SUM(amount) AS prescriptionFee, SUM(CASE WHEN typeString LIKE '%西药%' THEN amount ELSE 0 END) AS westernDrugFee, SUM(CASE WHEN typeString LIKE '%中草药%' THEN amount ELSE 0 END) AS chineseHerbalFee, SUM(CASE WHEN typeString LIKE '%中成药%' THEN amount ELSE 0 END) AS chinesePatentFee, SUM(CASE WHEN typeString LIKE '%治疗%' THEN amount ELSE 0 END) AS treatmentFee, SUM(CASE WHEN typeString LIKE '%诊查%' THEN amount ELSE 0 END) AS consultFee, SUM(CASE WHEN typeString LIKE '%材料%' THEN amount ELSE 0 END) AS materialFee, SUM(CASE WHEN typeString LIKE '%其他%' THEN amount ELSE 0 END) AS otherFee, SUM(CASE WHEN typeString LIKE '%附加%' THEN amount ELSE 0 END) AS additionalFee FROM bq_bill_not_charged WHERE deleted = 0 AND visitTime >= #{startTime} AND visitTime <= #{endTime} AND doctor = #{doctor} GROUP BY doctor ) bill ON bill.doctor = d.doctor LEFT JOIN ( /* 药房销售：实收总额 + 成本（operatorPerson 对应医生姓名） */ SELECT operatorPerson, SUM(CAST(actualAmount AS DECIMAL(15,2))) AS actualTotal, SUM(CAST(amount AS DECIMAL(15,2)) - CAST(actualAmount AS DECIMAL(15,2))) AS costTotal FROM bq_drug_sales WHERE deleted = 0 AND created >= #{startTime} AND created <= #{endTime} AND operatorPerson = #{doctor} GROUP BY operatorPerson ) sales ON sales.operatorPerson = d.doctor ORDER BY d.doctor

SELECT
    ROUND(COALESCE((
        SELECT SUM(CAST(actualAmount AS DECIMAL(15,2)))
        FROM bq_drug_sales
        WHERE deleted = 0
        AND created >= #{startTime}
        AND created <= #{endTime}
        AND operatorPerson = #{doctor}
    ), 0), 2) AS totalSales,
    ROUND(COALESCE((
        SELECT SUM(CAST(amount AS DECIMAL(15,2)) - CAST(actualAmount AS DECIMAL(15,2)))
        FROM bq_drug_sales
        WHERE deleted = 0
        AND created >= #{startTime}
        AND created <= #{endTime}
        AND operatorPerson = #{doctor}
    ), 0), 2) AS totalCost,
    ROUND(
        COALESCE((
            SELECT SUM(CAST(actualAmount AS DECIMAL(15,2)))
            FROM bq_drug_sales
            WHERE deleted = 0
            AND created >= #{startTime}
            AND created <= #{endTime}
            AND operatorPerson = #{doctor}
        ), 0) -
        COALESCE((
            SELECT SUM(CAST(amount AS DECIMAL(15,2)) - CAST(actualAmount AS DECIMAL(15,2)))
            FROM bq_drug_sales
            WHERE deleted = 0
            AND created >= #{startTime}
            AND created <= #{endTime}
            AND operatorPerson = #{doctor}
        ), 0)
    , 2) AS totalProfit
